gold.text:
extends Control

var _thread: Thread = null
var _closing: bool = false
var _target: TextureRect

func _ready() -> void:
    _target = get_node_or_null("TextureRect") as TextureRect

func _on_load_pressed() -> void:
    if _closing or _thread != null:
        return
    _thread = Thread.new()
    var err := _thread.start(_bg_load.bind("res://mona.png"))
    if err != OK:
        _thread = null
        push_error("Worker start failed: %s" % error_string(err))

func _bg_load(path: String) -> Texture2D:
    var tex := load(path) as Texture2D
    _finish_on_main.call_deferred()
    return tex

func _finish_on_main() -> void:
    if _closing or _thread == null:
        return
    var tex: Texture2D = _thread.wait_to_finish()
    _thread = null
    if tex == null:
        push_error("Texture load failed")
        return
    if is_instance_valid(_target):
        _target.texture = tex

func _exit_tree() -> void:
    _closing = true
    if _thread != null and _thread.is_started():
        _thread.wait_to_finish()
    _thread = null
